scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "Collection Hub V3 (just a reopen)",
   Icon = 0, -- Icon in Topbar. Can use Lucide Icons (string) or Roblox Image (number). 0 to use no icon (default).
   LoadingTitle = "Rayfield Interface Suite by Sirius",
   LoadingSubtitle = "Cavity Hub got taken down idk why",
   ShowText = "Cavity", -- for mobile users to unhide rayfield, change if you'd like
   Theme = "Default", -- Check https://docs.sirius.menu/rayfield/configuration/themes

   ToggleUIKeybind = "K", -- The keybind to toggle the UI visibility (string like "K" or Enum.KeyCode)

   DisableRayfieldPrompts = false,
   DisableBuildWarnings = false, -- Prevents Rayfield from warning when the script has a version mismatch with the interface

   ConfigurationSaving = {
      Enabled = false,
      FolderName = nil, -- Create a custom folder for your hub/game
      FileName = "Big Hub"
   },

   Discord = {
      Enabled = false, -- Prompt the user to join your Discord server if their executor supports it
      Invite = "noinvitelink", -- The Discord invite code, do not include discord.gg/. E.g. discord.gg/ ABCD would be ABCD
      RememberJoins = true -- Set this to false to make them join the discord every time they load it up
   },

   KeySystem = false, -- Set this to true to use our key system
   KeySettings = {
      Title = "Emergency Alarm🔥",
      Subtitle = "Emergency! I accidentally turn it to true!",
      Note = "Pass: ABCD", -- Use this to tell the user how to get a key
      FileName = "Key", -- It is recommended to use something unique as other scripts using Rayfield may overwrite your key file
      SaveKey = true, -- The user's key will be saved, but if you change the key, they will be unable to use your script
      GrabKeyFromSite = false, -- If this is true, set Key below to the RAW site you would like Rayfield to get the key from
      Key = {"ABCD"} -- incase if i accidentally made it true
   }
})

local BPTab = Window:CreateTab("BP Section", nil) -- Title, Image

local Button1 = BPTab:CreateButton({
   Name = "tp to knife",
   Callback = function()
        game.Players.LocalPlayer.Character.Torso.CFrame = workspace.Map["Weapon Tables"].Knife.CFrame
   end,
})

local Button2 = BPTab:CreateButton({
   Name = "tp to Deagle",
   Callback = function()
        game.Players.LocalPlayer.Character.Torso.CFrame = workspace.Map["Weapon Tables"].Deagle.CFrame
   end,
})

local Button3 = BPTab:CreateButton({
   Name = "Heal Button(new!!!)",
   Callback = function()
        game.Players.LocalPlayer.Character.Torso.CFrame = workspace.Map.Tower.Traps.Buttons.Heal100Brick.CFrame
   end,
})

local FunTab = Window:CreateTab("Fun Client sided tab (sometimes FE)", nil) -- Title, Image

local Button4 = FunTab:CreateButton({
   Name = "Back flip R15",
   Callback = function()
        local animator = game.Players.LocalPlayer.Character.Humanoid.Animator
        local backflip = Instance.new("Animation")
        backflip.AnimationId = "rbxassetid://91583499354581"

        -- Load the animation onto the Animator
        local backflipTrack = animator:LoadAnimation(backflip)

        -- Play the animation
        backflipTrack:Play()

        -- (Optional) Wait for the animation to finish before doing something else
        backflipTrack.Completed:Wait(1)
        local sui = Instance.new("Sound")
        sui.SoundId = "rbxassetid://7681560017"
        sui.Parent = game.Workspace
        sui:Play()
   end,
})

local Button5 = BPTab:CreateButton({
   Name = "Remington tp",
   Callback = function()
        game.Players.LocalPlayer.Character.Torso.CFrame = workspace.Map["Weapon Tables"].Remington.CFrame
   end,
})

local Button6 = BPTab:CreateButton({
   Name = "Spas 12 TP(not sure if it works)",
   Callback = function()
        game.Players.LocalPlayer.Character.Torso.CFrame = workspace.Map["Weapon Tables"]:GetChildren()[15].CFrame
   end,
})
